import { useTranslation } from 'react-i18next';
import { CONTROL_POINT_SIDC, DRONE_SIDC, natoSymbol, targetHighlight, targetSidc, unitSidc } from '../symbology/nato';

// Each entry is a NATO symbol (generated by milsymbol from a SIDC code) plus its meaning; `direction`
// adds the direction-of-movement arrow.
const ITEMS: { sidc: string; key: string; highlight: 'engaged' | null; direction?: number }[] = [
  { sidc: DRONE_SIDC, key: 'drone', highlight: null },
  { sidc: CONTROL_POINT_SIDC, key: 'control', highlight: null },
  { sidc: targetSidc('detected'), key: 'targetDetected', highlight: null },
  { sidc: targetSidc('confirmed'), key: 'targetConfirmed', highlight: null },
  { sidc: targetSidc('engaged'), key: 'targetEngaged', highlight: targetHighlight('engaged') },
  { sidc: targetSidc('neutralized'), key: 'targetNeutralized', highlight: null },
  { sidc: unitSidc('enemy', 'infantry'), key: 'enemyInfantry', highlight: null },
  { sidc: unitSidc('enemy', 'position'), key: 'enemyPosition', highlight: null },
  { sidc: unitSidc('enemy', 'vehicle'), key: 'enemyVehicle', highlight: null, direction: 45 },
  { sidc: unitSidc('enemy', 'artillery'), key: 'enemyArtillery', highlight: null },
  { sidc: unitSidc('enemy', 'air_defense'), key: 'enemyAirDefense', highlight: null },
  { sidc: unitSidc('enemy', 'ew'), key: 'enemyEw', highlight: null },
  { sidc: unitSidc('enemy', 'radar'), key: 'enemyRadar', highlight: null },
  { sidc: unitSidc('ally', 'infantry'), key: 'allyInfantry', highlight: null },
];

export function Legend() {
  const { t } = useTranslation();
  return (
    <main className="legend">
      <header className="legend-header">
        <a href="/">{t('legend.back')}</a>
        <h1>{t('legend.title')}</h1>
      </header>
      <ul className="legend-list">
        {ITEMS.map((item) => (
          <li key={item.key}>
            {/* milsymbol output for our own constant SIDC codes */}
            <span
              className={item.highlight ? `legend-symbol is-${item.highlight}` : 'legend-symbol'}
              dangerouslySetInnerHTML={{ __html: natoSymbol(item.sidc, 40, item.direction).asSVG() }}
            />
            <span>{t(`legend.${item.key}`)}</span>
          </li>
        ))}
        <li>
          <span className="legend-symbol legend-text-only">↑</span>
          <span>{t('legend.wind')}</span>
        </li>
      </ul>
    </main>
  );
}
